import type { createStorefront } from "arky-sdk/storefront";
import type {
  AccountActor,
  Cart,
  ChargeResolution,
  CheckoutAcceptance,
  EpochMilliseconds,
  Order,
  OrderCredit,
  Payment,
  PaymentMethod,
  PaymentType,
  RecordedPayment,
  ResolvePaymentChargeParams,
  Return,
  StorefrontCart,
  StorefrontCheckoutAcceptance,
  StorefrontOrder,
  StorefrontOrderCredit,
  StorefrontOrderCreditSource,
  StorefrontOrderCreditStatus,
  StorefrontOrderPlacer,
  StorefrontOrderReceipt,
  StorefrontOrderReceiptDocument,
  StorefrontOrderReceiptType,
  StorefrontTaxCoreReceiptState,
  StorefrontFbihPrinterReceiptState,
  StorefrontCroatiaReceiptState,
  StorefrontPayment,
  StorefrontPaymentHold,
  StorefrontPaymentMethod,
  StorefrontPaymentMethodConsent,
  StorefrontPaymentType,
  StorefrontRecordedPayment,
  StorefrontRecordedPaymentStatus,
  StorefrontRecordedRefund,
  StorefrontRecordedRefundMethod,
  StorefrontRecordedRefundReturned,
  StorefrontRecordedRefundSent,
  StorefrontRecordedRefundStatus,
  StorefrontReturn,
  RecordedRefundMethod,
  RecordedRefundSent,
  StripeCardPaymentStatus,
} from "arky-sdk";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = Extract<K, keyof T> extends never ? true : false;
type Assignable<A, B> = A extends B ? true : false;
type Storefront = ReturnType<typeof createStorefront>;

export type StorefrontCopyContracts = [
  Assert<Assignable<Omit<Payment, "type">, Omit<StorefrontPayment, "type">>>,
  Assert<Assignable<Exclude<PaymentType, { type: "recorded" }>, StorefrontPaymentType>>,
  Assert<Assignable<Omit<Extract<PaymentType, { type: "recorded" }>, "refunds">, Omit<Extract<StorefrontPaymentType, { type: "recorded" }>, "refunds">>>,
  Assert<Equal<Exclude<RecordedRefundMethod, { type: "cash_with_identity_document" }>, StorefrontRecordedRefundMethod>>,
  Assert<Missing<StorefrontPayment, "void">>,
  Assert<Assignable<Omit<Order, "source">, Omit<StorefrontOrder, "source" | "invoices" | "receipts" | "credits">>>,
  Assert<Missing<Order, "invoices">>,
  Assert<Missing<Order, "receipts">>,
  Assert<Missing<Order, "credits">>,
  Assert<Equal<StorefrontOrder["receipts"], StorefrontOrderReceipt[]>>,
  Assert<Equal<keyof StorefrontOrderReceipt, "id" | "type" | "document" | "created_at">>,
  Assert<Equal<StorefrontOrderReceipt["type"], StorefrontOrderReceiptType>>,
  Assert<Equal<StorefrontOrderReceiptType, "sale" | "advance" | "next_advance" | "advance_settle" | "advance_return" | "advance_correction" | "final" | "refund" | "correction" | "copy">>,
  Assert<Equal<StorefrontOrderReceiptDocument, { type: "tax_core"; state: StorefrontTaxCoreReceiptState } | { type: "fbih_printer"; state: StorefrontFbihPrinterReceiptState } | { type: "croatia_cis"; number: string; state: StorefrontCroatiaReceiptState }>>,
  Assert<Equal<StorefrontTaxCoreReceiptState, { type: "requested" } | { type: "sending" } | { type: "done"; invoice_number: string; verification_url: string } | { type: "done_on_other_device"; invoice_number: string } | { type: "refused" } | { type: "unknown" } | { type: "confirmed_not_issued" }>>,
  Assert<Equal<StorefrontFbihPrinterReceiptState, { type: "requested" } | { type: "sending" } | { type: "done"; receipt_number: number } | { type: "written_by_hand"; hand_number: string } | { type: "printing_after_hand"; hand_number: string } | { type: "done_after_hand"; hand_number: string; receipt_number: number } | { type: "print_failed_after_hand"; hand_number: string } | { type: "done_on_other_device"; receipt_number: string } | { type: "refused" } | { type: "unknown" } | { type: "confirmed_not_issued" }>>,
  Assert<Missing<Extract<StorefrontFbihPrinterReceiptState, { type: "written_by_hand" }>, "written_at" | "by">>,
  Assert<Missing<Extract<StorefrontFbihPrinterReceiptState, { type: "printing_after_hand" }>, "claim">>,
  Assert<Missing<Extract<StorefrontFbihPrinterReceiptState, { type: "print_failed_after_hand" }>, "error">>,
  Assert<Missing<Extract<StorefrontTaxCoreReceiptState, { type: "done_on_other_device" }>, "issued_at" | "by">>,
  Assert<Equal<StorefrontCroatiaReceiptState, { type: "requested" } | { type: "sending" } | { type: "done"; jir: string } | { type: "issued_offline" } | { type: "delivering" } | { type: "refused" }>>,
  Assert<Missing<Extract<StorefrontTaxCoreReceiptState, { type: "sending" }>, "claim">>,
  Assert<Missing<Extract<StorefrontTaxCoreReceiptState, { type: "done" }>, "signed_at" | "sdc_date_time">>,
  Assert<Missing<Extract<StorefrontCroatiaReceiptState, { type: "issued_offline" }>, "clearance_due_at">>,
  Assert<Missing<StorefrontOrderReceipt, "store_id" | "order_id" | "fiscal_device_id" | "kind" | "updated_at">>,
  Assert<Equal<StorefrontOrder["credits"], StorefrontOrderCredit[]>>,
  Assert<Assignable<OrderCredit, StorefrontOrderCredit>>,
  Assert<Equal<keyof StorefrontOrderCredit, "id" | "store_id" | "order_id" | "source" | "status" | "created_at" | "updated_at" | "currency" | "total">>,
  Assert<Missing<StorefrontOrderCredit, "allocations">>,
  Assert<Equal<StorefrontOrderCreditSource, { type: "cancellation" } | { type: "return"; return_id: string } | { type: "account" } | { type: "add_on_taken_off"; booked_add_on_id: string } | { type: "system" }>>,
  Assert<Equal<StorefrontOrderCreditStatus, { type: "active" } | { type: "voided"; voided_at: EpochMilliseconds }>>,
  Assert<Equal<Payment["payment_option_key"], string>>,
  Assert<Equal<StorefrontPayment["payment_option_key"], string>>,
  Assert<Equal<StorefrontOrderPlacer, { type: "customer"; customer_id: string } | { type: "account" }>>,
  Assert<Assignable<Cart, StorefrontCart>>,
  Assert<Assignable<Return, StorefrontReturn>>,
  Assert<Assignable<PaymentMethod, StorefrontPaymentMethod>>,
  Assert<Assignable<CheckoutAcceptance, StorefrontCheckoutAcceptance>>,
  Assert<Equal<keyof StorefrontPayment, "id" | "store_id" | "order_id" | "payment_option_id" | "payment_option_key" | "money" | "type" | "holds" | "status" | "created_at" | "updated_at">>,
  Assert<Equal<keyof StorefrontPaymentHold, "id" | "opened_at" | "status">>,
  Assert<Missing<StorefrontRecordedPayment, "recorded_by" | "reference">>,
  Assert<Equal<StorefrontRecordedPayment["method"], RecordedPayment["method"]>>,
  Assert<Equal<StorefrontRecordedPaymentStatus, { type: "active" } | { type: "voided"; at: EpochMilliseconds }>>,
  Assert<Missing<Extract<StorefrontPayment["type"], { type: "stripe_checkout" }>, "receipt_device">>,
  Assert<Missing<Extract<StorefrontPayment["type"], { type: "monri_card" }>, "receipt_device">>,
  Assert<Missing<StorefrontRecordedRefund, "request">>,
  Assert<Equal<StorefrontRecordedRefund["status"], StorefrontRecordedRefundStatus>>,
  Assert<Equal<StorefrontRecordedRefundStatus, { type: "requested" } | ({ type: "sent" } & StorefrontRecordedRefundSent) | { type: "returned"; sent: StorefrontRecordedRefundSent; returned: StorefrontRecordedRefundReturned } | { type: "cancelled" }>>,
  Assert<Equal<StorefrontRecordedRefundSent, { recorded_at: EpochMilliseconds; method: StorefrontRecordedRefundMethod }>>,
  Assert<Equal<StorefrontRecordedRefundMethod, { type: "cash" } | { type: "card" } | { type: "bank_transfer" } | { type: "other" }>>,
  Assert<Equal<RecordedRefundSent["method"], RecordedRefundMethod>>,
  Assert<Equal<StorefrontRecordedRefundReturned, { recorded_at: EpochMilliseconds }>>,
  Assert<Missing<StorefrontRecordedRefundSent, "recorded_by" | "reference">>,
  Assert<Missing<StorefrontRecordedRefundReturned, "recorded_by" | "reference" | "method">>,
  Assert<Missing<StorefrontPaymentMethodConsent, "given_by">>,
  Assert<Missing<StorefrontOrder, "placed_by">>,
  Assert<Missing<StorefrontReturn, "reviewed_by" | "actor">>,
  Assert<Equal<ResolvePaymentChargeParams["outcome"], ChargeResolution>>,
  Assert<Equal<Extract<StripeCardPaymentStatus, { type: "confirmed_not_made" }>, { type: "confirmed_not_made"; by: AccountActor }>>,
  Assert<Equal<Awaited<ReturnType<Storefront["eshop"]["order"]["get"]>>, StorefrontOrder>>,
];
